  registryHuawei: _('华为云镜像', 'Huawei Cloud Mirror', '華為雲鏡像'),
  installBtn: _('一键安装', 'Install', '一鍵安裝', 'ワンクリックインストール', '원클릭 설치', 'Cài đặt nhanh', 'Instalación rápida', 'Instalação rápida', 'Быстрая установка', 'Installation rapide', 'Schnellinstallation'),
  methodHintNpm: _('通过 npm 安装所选 OpenClaw 版本，需要本机已安装兼容版本的 Node.js 和 npm。', 'Installs the selected OpenClaw edition via npm and requires compatible local Node.js and npm.', '透過 npm 安裝所選 OpenClaw 版本，需要本機已安裝相容版本的 Node.js 和 npm。', '選択した OpenClaw を npm でインストールします。互換性のある Node.js と npm が必要です。', '선택한 OpenClaw를 npm으로 설치하며 호환되는 Node.js와 npm이 필요합니다.', 'Cài bản OpenClaw đã chọn qua npm và yêu cầu Node.js cùng npm tương thích.', 'Instala la edición de OpenClaw seleccionada mediante npm y requiere Node.js y npm compatibles.', 'Instala a edição do OpenClaw selecionada via npm e requer Node.js e npm compatíveis.', 'Устанавливает выбранную редакцию OpenClaw через npm; требуются совместимые Node.js и npm.', 'Installe l’édition OpenClaw sélectionnée via npm et nécessite des versions compatibles de Node.js et npm.', 'Installiert die ausgewählte OpenClaw-Ausgabe über npm und benötigt kompatible Versionen von Node.js und npm.'),
  envHintTitle: _('找不到已安装的 OpenClaw？', 'Can\'t find installed OpenClaw?', '找不到已安裝的 OpenClaw？'),
