  nodeManualInstallHtml: _('<strong>Windows:</strong> 下载 <a href="https://nodejs.org/" target="_blank" style="color:var(--accent)">nodejs.org</a> 安装包（建议 LTS）<br><strong>macOS:</strong> 访问 <a href="https://nodejs.org/" target="_blank" style="color:var(--accent)">nodejs.org</a> 或执行 <code style="background:var(--bg-secondary);padding:2px 4px;border-radius:3px">brew install node</code><br><strong>Linux:</strong> <code style="background:var(--bg-secondary);padding:2px 4px;border-radius:3px">sudo apt install nodejs npm</code> 或 <code style="background:var(--bg-secondary);padding:2px 4px;border-radius:3px">sudo yum install nodejs npm</code>', '<strong>Windows:</strong> Download from <a href="https://nodejs.org/" target="_blank" style="color:var(--accent)">nodejs.org</a> (LTS recommended)<br><strong>macOS:</strong> Visit <a href="https://nodejs.org/" target="_blank" style="color:var(--accent)">nodejs.org</a> or run <code style="background:var(--bg-secondary);padding:2px 4px;border-radius:3px">brew install node</code><br><strong>Linux:</strong> <code style="background:var(--bg-secondary);padding:2px 4px;border-radius:3px">sudo apt install nodejs npm</code> or <code style="background:var(--bg-secondary);padding:2px 4px;border-radius:3px">sudo yum install nodejs npm</code>', '<strong>Windows:</strong> 下載 <a href="https://nodejs.org/" target="_blank" style="color:var(--accent)">nodejs.org</a> 安裝包（建議 LTS）<br><strong>macOS:</strong> 造訪 <a href="https://nodejs.org/" target="_blank" style="color:var(--accent)">nodejs.org</a> 或執行 <code style="background:var(--bg-secondary);padding:2px 4px;border-radius:3px">brew install node</code><br><strong>Linux:</strong> <code style="background:var(--bg-secondary);padding:2px 4px;border-radius:3px">sudo apt install nodejs npm</code> 或 <code style="background:var(--bg-secondary);padding:2px 4px;border-radius:3px">sudo yum install nodejs npm</code>'),
